const steps=[
['Vehicle','Rental agreement or VIN','windscreen.jpg','Photograph the rental agreement, vehicle sticker or VIN so this record can be tied to the correct car.','Make the vehicle number or VIN readable.'],
['Vehicle','Odometer and fuel','windows.jpg','Turn on the dashboard and capture the mileage, fuel or charge level, and warning lights.','Keep every number sharp and visible.'],
['Exterior','Front overview','hood.jpg','Stand several steps back and photograph the full front of the vehicle straight on.','Include the bumper, hood, windshield and both corners.'],
['Exterior','Front-left corner','lights.jpg','Capture the driver-side front corner at a 45° angle.','Show the bumper, headlight, fender and front wheel.'],
['Exterior','Driver side','bumpers.jpg','Photograph the entire driver side from bumper to bumper.','Keep both wheels and all doors in the frame.'],
['Exterior','Rear-left corner','bumpers.jpg','Capture the driver-side rear corner at a 45° angle.','Show the rear door, quarter panel, light and bumper.'],
['Exterior','Rear overview','bumpers.jpg','Stand back and photograph the full rear of the vehicle straight on.','Include the plate, trunk or tailgate, lights and bumper.'],
['Exterior','Rear-right corner','bumpers.jpg','Capture the passenger-side rear corner at a 45° angle.','Show the rear door, quarter panel, light and bumper.'],
['Exterior','Passenger side','bumpers.jpg','Photograph the entire passenger side from bumper to bumper.','Keep both wheels and all doors in the frame.'],
['Exterior','Front-right corner','lights.jpg','Capture the passenger-side front corner at a 45° angle.','Show the bumper, headlight, fender and front wheel.'],
['Exterior','Windshield and roof','roof.jpg','Capture the full windshield and roof, including glass, rails and antennas.','Check carefully for chips, cracks and dents.'],
['Exterior','Lights and mirrors','mirrors.jpg','Photograph the lights and both mirror housings clearly.','Capture any cracked lenses or scraped mirror caps.'],
['Wheels','Front-left wheel','bumpers.jpg','Take a close, straight photo of the entire tire and rim.','Include the tire sidewall and edge of the fender.'],
['Wheels','Rear-left wheel','bumpers.jpg','Take a close, straight photo of the entire tire and rim.','Look for curb rash, cuts and low tire pressure.'],
['Wheels','Rear-right wheel','bumpers.jpg','Take a close, straight photo of the entire tire and rim.','Look for curb rash, cuts and low tire pressure.'],
['Wheels','Front-right wheel','bumpers.jpg','Take a close, straight photo of the entire tire and rim.','Include the tire sidewall and edge of the fender.'],
['Interior','Dashboard and console','windows.jpg','Photograph the full dashboard, center console and controls from the rear seat.','Show warning lights and the condition of every screen.'],
['Interior','Front seats','windows.jpg','Photograph both front seats, floor mats and door trim.','Document stains, tears, burns and missing items.'],
['Interior','Rear seats','windows.jpg','Photograph the complete rear seating area, belts and floor.','Move clutter so every surface is visible.'],
['Interior','Trunk or cargo area','roof.jpg','Open the trunk and photograph the full cargo area and spare-wheel compartment.','Include supplied cables, tools and accessories.']
].map(([section,title,image,copy,tip])=>({section,title,image:`assets/${image}`,copy,tip}));
const $=id=>document.getElementById(id),state=JSON.parse(localStorage.getItem('rental-inspection-v2')||'{}');
state.saved||=[];state.damage||={};state.notes||={};state.company||='';state.plate||='';
const captured=new Map();let current=0,filter='All';const views=[$('overview'),$('captureView'),$('reviewView')];
const saveState=()=>localStorage.setItem('rental-inspection-v2',JSON.stringify(state));
const isSaved=i=>state.saved.includes(i);const show=view=>{views.forEach(v=>v.classList.toggle('hidden',v!==view));window.scrollTo(0,0)};
const slug=v=>v.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'');
function renderOverview(){
 const sections=['All',...new Set(steps.map(s=>s.section))];
 $('filters').innerHTML=sections.map(n=>`<button class="${filter===n?'active':''}" data-filter="${n}">${n}</button>`).join('');
 $('filters').querySelectorAll('button').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;renderOverview()});
 const groups=[...new Set(steps.filter(s=>filter==='All'||s.section===filter).map(s=>s.section))];
 $('checklist').innerHTML=groups.map(group=>{const list=steps.map((s,i)=>({...s,i})).filter(s=>s.section===group),done=list.filter(s=>isSaved(s.i)).length;return `<section class="checklist-section"><div class="section-title"><div><p class="eyebrow">${done} OF ${list.length} SAVED</p><h3>${group}</h3></div><span>${done===list.length?'Complete':'Required'}</span></div><div class="angle-list">${list.map(s=>`<button class="angle-row ${isSaved(s.i)?'saved':captured.has(s.i)?'captured':''}" data-step="${s.i}"><img src="${captured.get(s.i)?.url||s.image}" alt=""><span class="angle-copy"><strong>${s.title}</strong><small>${isSaved(s.i)?'Saved to Photos':captured.has(s.i)?'Ready to save':'Photo needed'}${state.damage[s.i]?' · Damage marked':''}</small></span><i>${isSaved(s.i)?'✓':'›'}</i></button>`).join('')}</div></section>`}).join('');
 document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>openStep(+b.dataset.step));updateProgress();
}
function updateProgress(){const count=state.saved.length,pct=Math.round(count/steps.length*100),next=steps.findIndex((_,i)=>!isSaved(i));$('progressText').textContent=`${pct}%`;$('savedCount').textContent=`${count} of ${steps.length}`;$('progressBar').style.width=`${pct}%`;$('progressHint').textContent=count===steps.length?'Evidence set complete':`${steps.length-count} required angle${steps.length-count===1?'':'s'} remaining`;$('continueBtn').innerHTML=count===steps.length?'Review completed inspection <span>→</span>':`${count?'Continue':'Start'} inspection <span>→</span>`;$('continueBtn').onclick=()=>count===steps.length?openReview():openStep(next<0?0:next)}
function openStep(index){current=Math.max(0,Math.min(index,steps.length-1));const s=steps[current],photo=captured.get(current);show($('captureView'));$('guideImage').src=photo?.url||s.image;$('guideImage').alt=photo?`Your photo of ${s.title}`:`Reference for ${s.title}`;$('sectionBadge').textContent=s.section;$('stepCount').textContent=`${current+1} / ${steps.length}`;$('captureEyebrow').textContent=`${s.section.toUpperCase()} CHECK`;$('guideTitle').textContent=s.title;$('guideCopy').textContent=s.copy;$('guideTip').textContent=s.tip;$('photoStatus').textContent=isSaved(current)?'Saved to Photos':photo?'Ready to save':'Photo needed';$('photoStatus').className=`photo-status ${isSaved(current)?'saved':photo?'captured':''}`;$('cameraLabel').textContent=photo?'Retake photo':'Open camera';$('savePhotoBtn').classList.toggle('hidden',!photo);$('captureStatus').textContent=isSaved(current)?'Marked as saved to your iPhone Photos.':photo?'Tap Save, then choose “Save Image” in the share sheet.':"Uses your iPhone's rear camera.";$('damageToggle').checked=!!state.damage[current];$('noteWrap').classList.toggle('hidden',!state.damage[current]);$('damageNote').value=state.notes[current]||'';$('prevBtn').disabled=current===0;$('nextBtn').innerHTML=current===steps.length-1?'Review evidence <span>→</span>':'Next angle <span>→</span>'}
function openReview(){show($('reviewView'));const missing=steps.length-state.saved.length,damage=Object.values(state.damage).filter(Boolean).length;$('reviewSaved').textContent=state.saved.length;$('reviewMissing').textContent=missing;$('reviewDamage').textContent=damage;$('reviewTitle').textContent=missing?'Inspection needs attention':'Evidence set complete';$('reviewSubtitle').textContent=missing?`Capture and save ${missing} remaining photo${missing===1?'':'s'} before returning the vehicle.`:'Every required angle is marked as saved.';$('reviewList').innerHTML=steps.map((s,i)=>`<button data-review-step="${i}" class="review-row ${isSaved(i)?'saved':''}"><span>${isSaved(i)?'✓':'!'}</span><div><strong>${s.title}</strong><small>${s.section}${state.damage[i]?` · Damage: ${state.notes[i]||'marked'}`:''}</small></div><i>›</i></button>`).join('');document.querySelectorAll('[data-review-step]').forEach(b=>b.onclick=()=>openStep(+b.dataset.reviewStep))}
$('cameraBtn').onclick=()=>{$('cameraInput').value='';$('cameraInput').click()};
$('cameraInput').onchange=e=>{const file=e.target.files?.[0];if(!file)return;const old=captured.get(current);if(old)URL.revokeObjectURL(old.url);captured.set(current,{file,url:URL.createObjectURL(file)});state.saved=state.saved.filter(i=>i!==current);saveState();openStep(current)};
$('savePhotoBtn').onclick=async()=>{const photo=captured.get(current);if(!photo)return;try{if(navigator.canShare?.({files:[photo.file]}))await navigator.share({files:[photo.file],title:`Rental inspection — ${steps[current].title}`});else{const a=document.createElement('a');a.href=photo.url;a.download=`rental-inspection-${String(current+1).padStart(2,'0')}-${slug(steps[current].title)}.jpg`;a.click()}if(!isSaved(current))state.saved.push(current);saveState();openStep(current)}catch(error){if(error.name!=='AbortError')$('captureStatus').textContent='Could not open the share sheet. Please try again.'}};
$('damageToggle').onchange=e=>{state.damage[current]=e.target.checked;$('noteWrap').classList.toggle('hidden',!e.target.checked);saveState()};$('damageNote').oninput=e=>{state.notes[current]=e.target.value;saveState()};
$('companyInput').value=state.company;$('plateInput').value=state.plate;$('companyInput').oninput=e=>{state.company=e.target.value;saveState()};$('plateInput').oninput=e=>{state.plate=e.target.value.toUpperCase();e.target.value=state.plate;saveState()};
$('prevBtn').onclick=()=>openStep(current-1);$('nextBtn').onclick=()=>current===steps.length-1?openReview():openStep(current+1);$('backBtn').onclick=()=>{if(!$('overview').classList.contains('hidden'))history.back();else{show($('overview'));renderOverview()}};$('reviewBtn').onclick=openReview;$('progressButton').onclick=openReview;$('returnBtn').onclick=()=>{show($('overview'));renderOverview()};
$('sessionDate').textContent=new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date());renderOverview();
